package local.ondemand;
import java.net.*;import java.io.*;import java.util.*;import java.util.concurrent.*;
/** In-memory loopback range relay. Signed HTTPS addresses never reach VLC or logs. */
final class HttpsPlaybackBridge implements java.io.Closeable {
 final String source;final ServerSocket server;final ExecutorService clients=Executors.newFixedThreadPool(3);final Set<Socket> sockets=Collections.synchronizedSet(new HashSet<>());final Set<HttpURLConnection> upstreams=Collections.synchronizedSet(new HashSet<>());volatile boolean closed;volatile long bytes;volatile int requests;volatile String error="";
 HttpsPlaybackBridge(String url)throws IOException{source=url;server=new ServerSocket(0,3,InetAddress.getByName("127.0.0.1"));Thread accept=new Thread(()->{while(!closed)try{Socket socket=server.accept();sockets.add(socket);clients.submit(()->serve(socket));}catch(Exception e){if(!closed)error="Relay unavailable";}},"Cinema range relay");accept.setDaemon(true);accept.start();}
 String url(){return "http://127.0.0.1:"+server.getLocalPort()+"/video";}
 void serve(Socket socket){HttpURLConnection connection=null;try{socket.setSoTimeout(10000);BufferedReader reader=new BufferedReader(new InputStreamReader(socket.getInputStream(),"US-ASCII"));String request=reader.readLine();if(request==null)return;boolean head=request.startsWith("HEAD ");if(!(head||request.startsWith("GET ")))throw new IOException();String range="";int total=0;for(String line;(line=reader.readLine())!=null&&!line.isEmpty();){total+=line.length();if(total>8192)throw new IOException();if(line.toLowerCase(Locale.ROOT).startsWith("range:")){String value=line.substring(6).trim();if(value.matches("bytes=[0-9]*-[0-9]*"))range=value;}}URL url=new URL(source);for(int redirect=0;redirect<5;redirect++){if(closed||!url.getProtocol().equals("https")||url.getUserInfo()!=null)throw new IOException();connection=(HttpURLConnection)url.openConnection();upstreams.add(connection);connection.setConnectTimeout(8000);connection.setReadTimeout(10000);connection.setInstanceFollowRedirects(false);connection.setRequestMethod(head?"HEAD":"GET");connection.setRequestProperty("Accept-Encoding","identity");connection.setRequestProperty("User-Agent","PiOnDemand/0.5");if(!range.isEmpty())connection.setRequestProperty("Range",range);int status=connection.getResponseCode();if(status>=300&&status<400){String location=connection.getHeaderField("Location");if(location==null)throw new IOException();url=new URL(url,location);upstreams.remove(connection);connection.disconnect();connection=null;continue;}if(status!=200&&status!=206&&status!=416){error="Source HTTP "+status;throw new IOException();}String type=connection.getContentType();if(type!=null&&(type.contains("text/html")||type.contains("application/json")))throw new IOException();requests++;OutputStream out=socket.getOutputStream();StringBuilder response=new StringBuilder("HTTP/1.1 "+status+" "+(status==206?"Partial Content":status==416?"Range Not Satisfiable":"OK")+"\r\nConnection: close\r\nCache-Control: no-store\r\n");for(String name:new String[]{"Content-Length","Content-Range","Content-Type","Accept-Ranges"}){String value=connection.getHeaderField(name);if(value!=null&&!value.contains("\r")&&!value.contains("\n"))response.append(name).append(": ").append(value).append("\r\n");}response.append("\r\n");out.write(response.toString().getBytes("US-ASCII"));out.flush();if(!head&&status!=416)try(InputStream in=connection.getInputStream()){byte[] block=new byte[65536];int n;while(!closed&&(n=in.read(block))!=-1){out.write(block,0,n);bytes+=n;}}return;}throw new IOException();}catch(Exception e){if(!closed){if(error.isEmpty())error=e instanceof SocketTimeoutException?"Source response timed out":"Source connection interrupted";try{socket.getOutputStream().write("HTTP/1.1 502 Bad Gateway\r\nContent-Length: 0\r\nConnection: close\r\n\r\n".getBytes("US-ASCII"));}catch(Exception ignored){}}}finally{if(connection!=null){upstreams.remove(connection);connection.disconnect();}sockets.remove(socket);try{socket.close();}catch(Exception ignored){}}}
 public void close(){closed=true;try{server.close();}catch(Exception ignored){}synchronized(sockets){for(Socket s:sockets)try{s.close();}catch(Exception ignored){}}synchronized(upstreams){for(HttpURLConnection c:upstreams)c.disconnect();}clients.shutdownNow();}
}
